#include "pch.hxx"

#include "lua/lua_prelude.hxx"

// prelude/*.lua as text - generated by cmake/EmbedText.cmake (src/lua/CMakeLists.txt), one string_view per
// file, named after it.
#include "lua/lua_prelude_text.hxx"

namespace
{
namespace text = tw::lua::prelude::text;

// **The one list of sections**, in the order they run - and harness/lua/ljtest reads this table to run the
// same files in the same order, so a line here is all a new section needs. The chunk name is the file's
// name under `tw.`, which is also the convention ljtest relies on to find the file.
//
// The order is not a formality: each section takes what it needs from the ones before it through `S`, and
// tw.sandbox must stay last - every section above it has already captured, into locals, the names it
// removes (ffi for the casts, debug for tracebacks and caller places).
const tw::lua::prelude::section k_sections[] = {
    { "=tw.abi", text::abi },
    { "=tw.core", text::core },
    { "=tw.channels", text::channels },
    { "=tw.hud", text::hud },
    { "=tw.callbacks", text::callbacks },
    { "=tw.ui", text::ui },
    { "=tw.storage", text::storage },
    { "=tw.sandbox", text::sandbox },
};
} // namespace

namespace tw::lua::prelude
{
std::span<const section> sections() noexcept
{
    return k_sections;
}
} // namespace tw::lua::prelude
